using System.Collections.Generic;
using UnityEngine;
public class ShockDart : Projectile
{
	private static GameObject prefab;
	public ParticleSystem lightPartSys;
	private List<GameObject> targetList;
	private bool targetHit;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/ShockDart.prefab"));
	public override void Start()
	{
		base.Start();
		PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(3, transform.position);
		SoundManager.PlayWithDistAndSPR("ShockDart", transform.position);
	}
	public override void ResetProjectile()
	{
		if (lightPartSys != null)
		{
			lightPartSys.Stop();
			lightPartSys.transform.SetParent(null);
			Object.Destroy(lightPartSys.gameObject, 0.25f);
		}
		PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(5, transform.position);
		SoundManager.PlayWithDistAndSPR("LightningBurst", transform.position, 1.25f);
		base.ResetProjectile();
	}
	public void InitBounce()
	{
		disableOnHit = false;
		ricochet = true;
		moveSpeed = 28f;
		flyTime = 0.4f;
	}
	public override void HandleCollision(Collider2D other)
	{
		if (!(other.transform.parent != null) || IsParentObject(other.gameObject))
		{
			return;
		}
		if (disableOnHit || calculatedDamage == 0)
		{
			flagForReset = true;
		}
		else
		{
			if (!ricochet || ricochetAmount <= 0)
			{
				return;
			}
			ricochetCounter++;
			if (ricochetCounter >= ricochetAmount)
			{
				ChaosStopwatch.Stop(flyStopwatchID);
				return;
			}
			targetList = Entity.GetAllTargetsInRange(targetGroup, (Vector2)transform.position + moveVector * ricochetRadius * 0.4f, ricochetRadius, playerTagOnly: false, null, other.transform.parent.gameObject, requireLOS: true, ChaosCollisions.layerUpperWallAndObst);
			if (targetList != null && targetList.Count > 0)
			{
				nextTargetInfo = Entity.GetTargetInfoFromObject(targetList[Random.Range(0, targetList.Count)]);
			}
			OnRicochet();
			ChaosStopwatch.Refresh(flyStopwatchID, flyTime);
			isPointedAtMoveVector = false;
			moveVector = ((nextTargetInfo != null) ? ((Vector2)(nextTargetInfo.hurtBoxPosition - transform.position).normalized) : (Random.insideUnitCircle - moveVector * 2f).normalized);
			attackBox.knockbackOverwriteVector = moveVector;
		}
	}
	public override void OnRicochet()
	{
		if (!targetHit)
		{
			targetHit = true;
			moveSpeed = 40f;
			flyTime = 0.25f;
		}
	}
}
using System.Collections.Generic;
using Chaos.AnimatorExtensions;
using UnityEngine;
public class ShockDragon : Projectile
{
	private static GameObject prefab;
	private static int emitCount = 10;
	public ParticleSystem lightEmitter;
	public Renderer trailRenderer;
	public Transform spriteTrans;
	private int skillLevel;
	private int shotIndex;
	public bool isEmpowered;
	public bool isUltimate;
	private List<GameObject> excludeList;
	private ChaosQuickStopwatch arcStopwatch = new ChaosQuickStopwatch();
	private float arcLerpValue;
	private bool arcPositive;
	private bool arcCompleted;
	private Vector2 initMoveVector;
	private Vector2 lerpExtVector;
	private Vector2 boundVector;
	private float arcRange = 4f;
	private float arcAccuracy = 1.125f;
	private float arcVariance = 1.25f;
	private int arcMaxCount = 4;
	private int arcFlipCount = 2;
	private int arcCounter;
	private bool arcFlipped;
	private float burstRadius = 2f;
	private bool riseStarted;
	private bool riseCompleted;
	private bool dropCompleted;
	private int dropStopwatchID = -1;
	private Vector2 currentPosition;
	private bool useParentPosition;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/ShockDragon.prefab"));
	public void Init(Vector2 givenVector, int givenLevel, int givenIndex, bool isPos, bool isEmp, bool isUlt, List<GameObject> givenList)
	{
		initMoveVector = givenVector;
		moveVector = givenVector;
		skillLevel = givenLevel;
		shotIndex = givenIndex;
		excludeList = givenList;
		arcPositive = isPos;
		if (isEmp)
		{
			isEmpowered = true;
			moveSpeed = 42f;
			arcRange = 5.25f;
			arcMaxCount = 5;
			arcAccuracy = 1f;
			arcVariance = 1f;
			burstRadius = 3f;
		}
		if (isUlt)
		{
			isUltimate = true;
			arcRange = 8f;
			arcFlipCount = 1;
			arcMaxCount = 3;
			goThroughWalls = true;
			useParentPosition = true;
		}
	}
	public override void Start()
	{
		base.Start();
		if (Projectile.projectileShootEvent != null)
		{
			Projectile.projectileShootEvent(this);
		}
		boundVector = Globals.GetPerpendicular(initMoveVector) * arcVariance;
		arcStopwatch.SetDelay(arcRange / Mathf.Max(1f, moveSpeed), stopCurrent: false, autoStart: true);
		if (lightEmitter != null)
		{
			lightEmitter.randomSeed = (uint)shotIndex;
			lightEmitter.Play();
			lightEmitter.Emit(emitCount);
		}
		if (spriteTrans != null)
		{
			spriteTrans.localEulerAngles = Globals.GetRotationVector(initMoveVector);
		}
		PlayBounceAudio();
	}
	public override void Update()
	{
		if (!arcCompleted)
		{
			return;
		}
		if (!riseCompleted)
		{
			if (!riseStarted)
			{
				riseStarted = true;
				rigidbody2D.velocity = Vector2.zero;
				spriteTrans.localEulerAngles = Globals.GetRotationVector(Vector2.up);
				anim.Play("Rise", -1, 0f);
				trailRenderer.sortingLayerName = "OverlayDoodad";
				trailRenderer.sortingOrder = 10;
				projectileSpriteRenderer.sortingLayerName = "OverlayDoodad";
				projectileSpriteRenderer.sortingOrder = 10;
				if (lightEmitter != null)
				{
					lightEmitter.Emit(emitCount);
				}
				if (isUltimate)
				{
					dropStopwatchID = ChaosStopwatch.Begin((float)shotIndex * 0.15f);
				}
				SoundManager.PlayWithDistAndSPR("Shockwave", transform.position);
			}
			else if (ChaosStopwatch.Check(dropStopwatchID) && anim.AnimPlayed())
			{
				riseCompleted = true;
				rigidbody2D.velocity = Vector2.zero;
				spriteTrans.localEulerAngles = Globals.GetRotationVector(Vector2.down);
				anim.Play("Land", -1, 0f);
				currentPosition = ((!useParentPosition || !(parentObject != null)) ? transform.position : parentObject.transform.position);
				currentPosition = Globals.GetLinecastVector(currentPosition, currentPosition + Random.insideUnitCircle * 3f, ChaosCollisions.layerAll);
				nextTargetInfo = Entity.GetClosestTarget(GameController.enemies, currentPosition, 12f, playerTagOnly: false, excludeList, parentObject, requireLOS: true, ChaosCollisions.layerAll);
				if (nextTargetInfo != null)
				{
					currentPosition = nextTargetInfo.position;
				}
				transform.position = Globals.GetLinecastVector(currentPosition, currentPosition + Random.insideUnitCircle * burstRadius * 0.5f, ChaosCollisions.layerAll);
			}
		}
		else if (!dropCompleted && anim.AnimPlayed())
		{
			dropCompleted = true;
			if (lightEmitter != null)
			{
				lightEmitter.Emit(emitCount);
				lightEmitter.transform.SetParent(null);
				Object.Destroy(lightEmitter.gameObject, 0.5f);
				lightEmitter = null;
			}
			CreateDropBurst(transform.position);
			ResetProjectile();
		}
	}
	public override void FixedUpdate()
	{
		if (arcCompleted)
		{
			return;
		}
		arcLerpValue = arcStopwatch.TimePercentage;
		lerpExtVector = arcAccuracy * Vector2.Lerp(-boundVector, boundVector, (!arcPositive) ? (1f - arcLerpValue) : arcLerpValue);
		moveVector = (initMoveVector + lerpExtVector).normalized;
		rigidbody2D.velocity = moveVector * moveSpeed;
		spriteTrans.localEulerAngles = Globals.GetRotationVector(moveVector);
		if (attackBox != null)
		{
			attackBox.knockbackOverwriteVector = moveVector;
		}
		if (!(arcLerpValue >= 1f))
		{
			return;
		}
		arcStopwatch.IsRunning = true;
		arcPositive = !arcPositive;
		arcCounter++;
		goThroughWalls = true;
		if (arcCounter < arcMaxCount)
		{
			if (arcCounter < arcFlipCount)
			{
				if (isUltimate)
				{
					PlayBounceAudio();
				}
				return;
			}
			if (isUltimate)
			{
				arcFlipCount = 2;
			}
			initMoveVector = -initMoveVector;
			arcFlipCount += arcFlipCount;
			arcFlipped = !arcFlipped;
			attackBox.ChangeAttackInfoLevel((!arcFlipped) ? skillLevel : (skillLevel + 1));
			attackBox.gameObject.SetActive(value: false);
			attackBox.gameObject.SetActive(value: true);
			PlayBounceAudio();
		}
		else
		{
			arcCompleted = true;
		}
	}
	public override void HandleWallCollision(Collider2D other)
	{
		arcCompleted = true;
		useParentPosition = true;
	}
	private void CreateDropBurst(Vector2 givenPosition)
	{
		attackBox.ChangeAttackInfoLevel(3);
		if (isEmpowered)
		{
			attackBox.atkInfo.shockChance = 1f;
		}
		AttackInfo.SetFloorTargets(attackBox.atkInfo.targetNames);
		LightningBurst.CreateBurst(givenPosition, attackBox.atkInfo, burstRadius);
		if (isEmpowered && !isUltimate)
		{
			Vector3 givenPosition2 = givenPosition;
			float givenScale = burstRadius * 0.5f;
			LightningBurst.CreateBurst(givenPosition2, string.Empty, string.Empty, 1, givenScale);
		}
		SoundManager.PlayAudioWithDistance("ThunderClap", givenPosition, null, 24f, 0.25f);
		CameraController.ShakeCamera(0.2f);
	}
	private void PlayBounceAudio()
	{
		string audioID = "ThunderBounce";
		Vector2? soundOrigin = transform.position;
		float standardPitchRange = SoundManager.StandardPitchRange;
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, 0.35f, standardPitchRange);
	}
}

