public class ShockLace : MonoBehaviour
{
	private static GameObject prefab;
	private static Vector2 positionOffset = new Vector2(0f, 0.5f);
	private string skillCategory;
	private string skillID;
	private Vector2 inputVector;
	public GameObject shockNodeObj;
	public int nodeCount = 12;
	private int minRange;
	private int maxRange;
	private float placeInterval = 0.025f;
	private int placeStopwatchID;
	private bool placeCompleted;
	public float atkRadius = 4f;
	public int atkCount = 16;
	public float atkInterval = 0.2f;
	private int atkStopwatchID;
	private bool atkCompleted;
	public int hitCount = 5;
	public float hitInterval = 0.125f;
	private ChaosQuickStopwatch destroyStopwatch = new ChaosQuickStopwatch(0.75f);
	private ParticleSystemOverride lfOverride = new ParticleSystemOverride
	{
		radius = 1f,
		startLifetime = 0.35f
	};
	private int[] indexArr;
	private int currentIndex;
	private int nextIndex;
	private int lastIndex;
	private Vector2 startPosition;
	private Vector2 spawnPosition;
	private Vector2[] vectorArr;
	private LightningStream currentLS;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/ShockLace.prefab"));
	private void Start()
	{
		startPosition = transform.position;
		minRange = (int)((float)nodeCount * 0.35f);
		maxRange = minRange * 2;
		vectorArr = new Vector2[nodeCount];
		indexArr = new int[nodeCount];
		for (int i = 0; i < nodeCount; i++)
		{
			indexArr[i] = i;
		}
		indexArr.Shuffle();
		placeStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, placeInterval, nodeCount);
	}
	private void FixedUpdate()
	{
		if (!placeCompleted)
		{
			switch (ChaosStopwatch.CheckInterval(placeStopwatchID))
			{
			case StopwatchState.Ready:
			{
				spawnPosition = Globals.GetLinecastVector(startPosition, startPosition + Globals.GetRotatedCircleVector(nodeCount, indexArr[currentIndex], inputVector) * atkRadius, ChaosCollisions.layerAllWallAndObst);
				Object.Instantiate(LightningStrike.Prefab, spawnPosition, Quaternion.identity);
				Object.Instantiate(shockNodeObj, spawnPosition, Quaternion.identity, transform).SetActive(value: true);
				ref Vector2 reference = ref vectorArr[indexArr[currentIndex]];
				reference = spawnPosition + positionOffset;
				currentIndex++;
				break;
			}
			case StopwatchState.Done:
				placeCompleted = true;
				atkStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, atkInterval, atkCount);
				currentIndex = indexArr[currentIndex - 1];
				lastIndex = currentIndex;
				break;
			}
		}
		else if (!atkCompleted)
		{
			switch (ChaosStopwatch.CheckInterval(atkStopwatchID))
			{
			case StopwatchState.Ready:
				nextIndex = (currentIndex + Random.Range(minRange, maxRange)) % nodeCount;
				if (lastIndex == nextIndex)
				{
					nextIndex = (nextIndex + 1) % nodeCount;
				}
				CreateLightStream(vectorArr[currentIndex], vectorArr[nextIndex]);
				lastIndex = currentIndex;
				currentIndex = nextIndex;
				break;
			case StopwatchState.Done:
				atkCompleted = true;
				destroyStopwatch.IsRunning = true;
				break;
			}
		}
		else if (!destroyStopwatch.IsRunning)
		{
			for (int i = 0; i < nodeCount; i++)
			{
				CreateParticleEffect(vectorArr[i]);
			}
			Object.Destroy(gameObject);
		}
	}
