	{
		currentLS = Globals.ChaosInst<LightningStream>(LightningStream.Prefab, null, startPos);
		currentLS.targetLocation = endPos;
		currentLS.attack.SetAttackInfo(skillCategory, skillID);
		currentLS.hitCount = hitCount;
		currentLS.hitInterval = hitInterval;
		CreateParticleEffect(startPos);
		CreateParticleEffect(endPos);
