public class Shuriken : Projectile
{
	[HideInInspector]
	public float homingBias = 5f;
	public float homingDuration = 0.75f;
	protected ChaosQuickStopwatch durationStopwatch;
	protected Vector2 targetVector;
	protected Vector2 prevVector;
	protected float baseMoveSpeed;
	protected float moveSpeedLerpValue;
	protected float calcBias;
	protected float timePercentage;
	protected bool homingCompleted;
	protected bool TargetExists => !homingCompleted && targetTrans != null;
	public override void Start()
	{
		base.Start();
		baseMoveSpeed = moveSpeed;
		SoundManager.PlayWithDistAndSPR("StandardThrow", transform.position);
		string audioID = "StandardSpin";
		Transform originTrans = transform;
		SoundManager.PlayAudioWithDistance(audioID, null, originTrans);
		if (targetTrans != null)
		{
			durationStopwatch = new ChaosQuickStopwatch(homingDuration);
			durationStopwatch.IsRunning = true;
		}
	}
	public override void FixedUpdate()
	{
		base.FixedUpdate();
		HandleSpeedUp();
		if (TargetExists)
		{
			HandleHomingMovement();
		}
	}
	public virtual void HandleSpeedUp()
	{
		if (moveSpeed < baseMoveSpeed)
		{
			moveSpeed += Time.fixedDeltaTime;
		}
	}
	public virtual void HandleHomingMovement()
	{
		timePercentage = durationStopwatch.TimePercentage;
		homingCompleted = timePercentage >= 1f;
		calcBias = Mathf.Lerp(1f, homingBias, 2f * ((!(timePercentage < 0.5f)) ? (1f - timePercentage) : timePercentage));
		targetVector = (targetTrans.position - transform.position).normalized;
		prevVector = moveVector;
		moveVector = (moveVector + targetVector * calcBias * Time.fixedDeltaTime).normalized;
		attackBox.knockbackOverwriteVector = moveVector;
		moveSpeedLerpValue = Vector2.Angle(prevVector, moveVector) * 0.00555f;
		moveSpeed = Mathf.Lerp(baseMoveSpeed, 0f, moveSpeedLerpValue);
	}
